import axios from "axios";

import { useUserStore } from "@/stores/user.ts";

const baseURL = import.meta.env.VITE_API_BASE || "/api/";

// 创建一个 axios 实例
const service = axios.create({
  baseURL: baseURL, // 所有的请求地址前缀部分
  timeout: 60000, // 请求超时时间毫秒
  withCredentials: true, // 异步请求携带cookie
  headers: {
    // 设置后端需要的传参类型
    "Content-Type": "application/json",
    "X-Requested-With": "XMLHttpRequest",
  },
});

// 请求拦截器 - no longer need to set X-Token header as we use cookies
service.interceptors.request.use(
  (config) => {
    // Cookies are automatically sent by the browser
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// 添加响应拦截器
service.interceptors.response.use(
  function (response) {
    return response.data;
  },
  async function (error) {
    const originalRequest = error.config;
    if (error.response && error.response.status === 401 && !originalRequest._retry) {
      originalRequest._retry = true;
      try {
        // Attempt to refresh token
        const refreshResponse = await service.post('/user/login/refresh');
        // Update user store with new user info
        const userStore = useUserStore();
        userStore.loadResponse(refreshResponse);
        return service(originalRequest);
      } catch (refreshError) {
        // If refresh fails, clear user store and redirect to login
        const userStore = useUserStore();
        userStore.clear();
        // You might want to redirect to login page here
        return Promise.reject(refreshError);
      }
    }
    return Promise.reject(error);
  }
);

declare module "axios" {
  interface AxiosInstance {
    (config: AxiosRequestConfig): Promise<any>;
  }
}

export default service;
