// md-editor-v3 扩展动态加载模块
// 将 katex、mermaid、prettier、cropper 等重依赖改为按需异步加载

import { config } from "md-editor-v3/lib/es/config.mjs";

let extensionsLoaded = false;
let loadPromise: Promise<void> | null = null;

/**
 * 异步加载 md-editor-v3 的重依赖扩展
 * 首次调用时触发加载，后续调用直接返回已完成的 Promise
 */
export const loadMdExtensions = (): Promise<void> => {
  if (extensionsLoaded) {
    return Promise.resolve();
  }

  if (loadPromise) {
    return loadPromise;
  }

  loadPromise = (async () => {
    try {
      // 并行加载所有重依赖
      const [
        { default: katex },
        { default: mermaid },
        { default: Cropper },
        { default: prettier },
        { default: parserMarkdown },
      ] = await Promise.all([
        import("katex"),
        import("mermaid"),
        import("cropperjs"),
        import("prettier"),
        import("prettier/plugins/markdown"),
      ]);

      // 动态加载 katex CSS
      await import("katex/dist/katex.min.css");
      await import("cropperjs/dist/cropper.css");

      // 更新 md-editor-v3 配置
      config({
        editorExtensions: {
          prettier: {
            prettierInstance: prettier,
            parserMarkdownInstance: parserMarkdown,
          },
          katex: {
            instance: katex,
          },
          cropper: {
            instance: Cropper,
          },
          mermaid: {
            instance: mermaid,
          },
        },
      });

      extensionsLoaded = true;
      console.log("Markdown extensions loaded (katex, mermaid, prettier, cropper)");
    } catch (e) {
      console.error("Failed to load markdown extensions:", e);
      loadPromise = null; // 允许重试
      throw e;
    }
  })();

  return loadPromise;
};

/**
 * 立即触发后台预加载（不阻塞，用于首屏后预热）
 */
export const preloadMdExtensions = () => {
  // 不等待，后台静默加载
  loadMdExtensions().catch(() => {});
};
